mapper.select:
select s.spu_id,s.spu_code,s.product_name,s.subtitle,s.main_image,c.category_name,b.brand_name,s.publish_status, count(k.sku_id) sku_count, coalesce(sum(coalesce(st.available_quantity,k.available_stock,0)),0) available_quantity, coalesce(sum(coalesce(st.locked_quantity,0)),0) locked_quantity, coalesce(sum(coalesce(st.sold_quantity,0)),0) sold_quantity, coalesce(sum(case when coalesce(st.available_quantity,k.available_stock,0) > 0 and coalesce(st.available_quantity,k.available_stock,0) <= coalesce(st.warning_threshold,0) then 1 else 0 end),0) low_stock_sku_count, coalesce(sum(case when coalesce(st.available_quantity,k.available_stock,0) <= 0 then 1 else 0 end),0) out_of_stock_sku_count, case when count(k.sku_id)=0 then 'OUT_OF_STOCK' when sum(case when coalesce(st.available_quantity,k.available_stock,0) <= 0 then 1 else 0 end) > 0 then 'OUT_OF_STOCK' when sum(case when coalesce(st.available_quantity,k.available_stock,0) > 0 and coalesce(st.available_quantity,k.available_stock,0) <= coalesce(st.warning_threshold,0) then 1 else 0 end) > 0 then 'LOW_STOCK' else 'HEALTHY' end stock_status, max(coalesce(st.update_time,s.update_time)) update_time from mall_spu s join mall_category c on c.category_id=s.category_id and c.del_flag='0' left join mall_brand b on b.brand_id=s.brand_id and b.del_flag='0' left join mall_sku k on k.spu_id=s.spu_id and k.del_flag='0' left join mall_stock st on st.sku_id=k.sku_id
s.del_flag='0' and (s.product_name like concat('%',#{productKeyword},'%') or s.subtitle like concat('%',#{productKeyword},'%')) and s.spu_code like concat('%',#{spuCode},'%') and k.sku_code like concat('%',#{skuCode},'%') and s.publish_status=#{publishStatus}
group by s.spu_id,s.spu_code,s.product_name,s.subtitle,s.main_image,c.category_name,b.brand_name,s.publish_status having count(k.sku_id)=0 or sum(case when coalesce(st.available_quantity,k.available_stock,0) <= 0 then 1 else 0 end) > 0 having sum(case when coalesce(st.available_quantity,k.available_stock,0) > 0 and coalesce(st.available_quantity,k.available_stock,0) <= coalesce(st.warning_threshold,0) then 1 else 0 end) > 0 and sum(case when coalesce(st.available_quantity,k.available_stock,0) <= 0 then 1 else 0 end)=0 having count(k.sku_id) > 0 and sum(case when coalesce(st.available_quantity,k.available_stock,0) <= coalesce(st.warning_threshold,0) then 1 else 0 end)=0 order by update_time desc,s.spu_id desc
